@Slf4j
public class VoicePickerChatbox {
	private final ChatboxPanelManager chatboxPanelManager;
	private final ClientThread clientThread;
	private final Client client;
	private final VoiceManager voiceManager;
	private final TextToSpeech textToSpeech;
	private final ModelRepository modelRepository;
	private final ElevenLabsVoiceRepository elevenLabsVoiceRepository;
	private final Provider<VoiceConfigChatboxTextInput> textInputProvider;
	private final Provider<VoiceSearchChatbox> voiceSearchProvider;

	private NPC npc;
	private String standardActorName;
	private String value = "";

	@Inject
	public VoicePickerChatbox(
		ChatboxPanelManager chatboxPanelManager,
		ClientThread clientThread,
		Client client,
		VoiceManager voiceManager,
		TextToSpeech textToSpeech,
		ModelRepository modelRepository,
		ElevenLabsVoiceRepository elevenLabsVoiceRepository,
		Provider<VoiceConfigChatboxTextInput> textInputProvider,
		Provider<VoiceSearchChatbox> voiceSearchProvider) {
		this.chatboxPanelManager = chatboxPanelManager;
		this.clientThread = clientThread;
		this.client = client;
		this.voiceManager = voiceManager;
		this.textToSpeech = textToSpeech;
		this.modelRepository = modelRepository;
		this.elevenLabsVoiceRepository = elevenLabsVoiceRepository;
		this.textInputProvider = textInputProvider;
		this.voiceSearchProvider = voiceSearchProvider;
	}

	public VoicePickerChatbox configNPC(@Nullable NPC npc) {
		this.npc = npc;
		return this;
	}

	public VoicePickerChatbox configUsername(@NonNull String standardActorName) {
		this.standardActorName = standardActorName;
		return this;
	}

	public VoicePickerChatbox value(@NonNull String value) {
		this.value = value;
		return this;
	}

	public void build() {
		VoiceConfigChatboxTextInput input = textInputProvider.get();
		input.onChooseVoice(() -> clientThread.invokeLater(() -> chooseVoice(input)))
			.onSubmit(text -> submit(input, text))
			.prompt("Voice for " + standardActorName)
			.value(value)
			.build();
	}

	private boolean submit(VoiceConfigChatboxTextInput input, String text) {
		if (text.isBlank()) {
			clientThread.invokeLater(() -> {
				if (hasAssignedVoice()) confirmClear();
			});
			return true;
		}

		VoiceID voiceID = VoiceID.fromIDString(text.trim());
		if (voiceID == null) {
			input.error("Not a valid voice ID, example: libritts:120");
			return false;
		}

		clientThread.invokeLater(() -> applyVoice(voiceID));
		return true;
	}

	private boolean hasAssignedVoice() {
		if (npc != null) return voiceManager.containsNPC(npc.getId(), standardActorName);
		return voiceManager.containsUsername(standardActorName);
	}

	private void confirmClear() {
		chatboxPanelManager.openTextMenuInput("Clear the voice for " + standardActorName + "?")
			.option("Yes", () -> clientThread.invokeLater(this::clearVoice))
			.option("No", () -> clientThread.invokeLater(this::build))
			.build();
	}

	private void chooseVoice(VoiceConfigChatboxTextInput input) {
		if (availableEngines().isEmpty()) {
			input.error("No voices available, start an engine first");
			return;
		}
		openEngineMenu();
	}

	private List<SpeechEngine> availableEngines() {
		return Arrays.stream(SpeechEngine.values())
			.filter(engine -> !activeModels(engine).isEmpty())
			.collect(Collectors.toList());
	}

	private void openEngineMenu() {
		List<SpeechEngine> engines = availableEngines();
		if (engines.isEmpty()) {
			build();
			return;
		}
		if (engines.size() == 1) {
			openModelMenu(engines.get(0), this::build);
			return;
		}

		ChatboxTextMenuInput menu = chatboxPanelManager.openTextMenuInput("Choose an engine");
		for (SpeechEngine engine : engines) {
			menu.option(engine.toString(),
				() -> clientThread.invokeLater(() -> openModelMenu(engine, this::openEngineMenu)));
		}
		menu.option("Back", () -> clientThread.invokeLater(this::build));
		menu.build();
	}

	private void openModelMenu(SpeechEngine engine, Runnable back) {
		List<VoiceSource> models = activeModels(engine);
		if (models.isEmpty()) {
			back.run();
			return;
		}
		if (models.size() == 1) {
			openVoiceSearch(models.get(0), back);
			return;
		}

		ChatboxTextMenuInput menu = chatboxPanelManager.openTextMenuInput("Choose a " + engine + " model");
		for (VoiceSource model : models) {
			menu.option(model.getModelLabel(),
				() -> clientThread.invokeLater(() -> openVoiceSearch(model, () -> openModelMenu(engine, back))));
		}
		menu.option("Back", () -> clientThread.invokeLater(back));
		menu.build();
	}

	private List<VoiceSource> activeModels(SpeechEngine engine) {
		List<VoiceSource> models = new ArrayList<>();
		if (engine == SpeechEngine.ELEVENLABS) {
			if (elevenLabsVoiceRepository.getVoices().isEmpty()) return models;

			for (ElevenLabsModel model : elevenLabsVoiceRepository.getEnabledModels()) {
				models.add(VoiceSource.ofModel(model.getId()));
			}
		}
		else {
			for (ModelRepository.ModelURL modelURL : modelRepository.getModelURLS()) {
				models.add(VoiceSource.ofModel(modelURL.getModelName()));
			}
		}
		models.removeIf(model -> !textToSpeech.isModelActive(model.getModelName()));
		return models;
	}

	private void openVoiceSearch(VoiceSource model, Runnable back) {
		List<VoiceSearchChatbox.Choice> voices = voicesFor(model.getModelName());
		if (voices.isEmpty()) {
			feedback(model + " has no voices available");
			back.run();
			return;
		}

		voiceSearchProvider.get()
			.voices(voices)
			.title(model.getModelLabel() + " voice for " + standardActorName)
			.onSelected(voiceID -> clientThread.invokeLater(() -> applyVoice(voiceID)))
			.onBack(() -> clientThread.invokeLater(back))
			.build();
	}

	private List<VoiceSearchChatbox.Choice> voicesFor(String modelName) {
		List<VoiceSearchChatbox.Choice> choices = new ArrayList<>();

		ElevenLabsModel elevenLabsModel = ElevenLabsModel.fromId(modelName);
		if (elevenLabsModel != null) {
			for (ElevenLabsVoice voice : elevenLabsVoiceRepository.getVoices()) {
				choices.add(VoiceSearchChatbox.Choice.of(label(voice.getName(), voice.getGender()),
					voice.toVoiceID(elevenLabsModel)));
			}
		}
		else {
			try {
				for (ModelRepository.VoiceMetadata voice : modelRepository.loadModelLocal(modelName).getVoiceMetadata()) {
					choices.add(VoiceSearchChatbox.Choice.of(label(voice.getName(), voice.getGender()), voice.toVoiceID()));
				}
			} catch (IOException e) {
				log.error("Failed to load the voices for {}", modelName, e);
			}
		}

		choices.sort(Comparator.comparing(choice -> choice.getLabel().toLowerCase()));
		return choices;
	}

	private static String label(String name, Gender gender) {
		if (gender == Gender.MALE) return name + " (M)";
		if (gender == Gender.FEMALE) return name + " (F)";
		return name;
	}

	private void applyVoice(VoiceID voiceID) {
		voiceManager.applyConfiguredVoice(npc, standardActorName, voiceID);
		feedback(standardActorName + " set to " + voiceID);
	}

	private void clearVoice() {
		voiceManager.clearConfiguredVoice(npc, standardActorName);
		feedback("Cleared the voice for " + standardActorName);
	}

	private void feedback(String message) {
		client.addChatMessage(ChatMessageType.CONSOLE, "", "Natural Speech: " + message, null);
	}
}

package dev.phyce.naturalspeech.ui.game;

import com.google.inject.Inject;
import dev.phyce.naturalspeech.tts.VoiceID;
import java.awt.event.KeyEvent;
import java.awt.event.MouseWheelEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import lombok.Value;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.game.chatbox.ChatboxTextInput;
import net.runelite.client.input.MouseWheelListener;

public class VoiceSearchChatbox extends ChatboxTextInput implements MouseWheelListener {

	private static final int FONT_SIZE = 16;
	private static final int LINE_HEIGHT = 15;
	private static final int PADDING = 6;

	private final ChatboxPanelManager chatboxPanelManager;

	private final List<Choice> choices = new ArrayList<>();
	private final List<Choice> results = new ArrayList<>();

	private Consumer<VoiceID> onSelected;
	private Runnable onBack;

	private int scrollOffset = 0;
	private int visibleRows = 1;

	@Inject
	protected VoiceSearchChatbox(ChatboxPanelManager chatboxPanelManager, ClientThread clientThread) {
		super(chatboxPanelManager, clientThread);
		this.chatboxPanelManager = chatboxPanelManager;

		lines(1);
		prompt("Search voices");

		onChanged(search -> clientThread.invokeLater(() -> {
			filter();
			update();
		}));
	}

	public VoiceSearchChatbox voices(List<Choice> voices) {
		choices.clear();
		choices.addAll(voices);
		filter();
		return this;
	}

	public VoiceSearchChatbox title(String title) {
		prompt(title);
		return this;
	}

	public VoiceSearchChatbox onSelected(Consumer<VoiceID> onSelected) {
		this.onSelected = onSelected;
		return this;
	}

	public VoiceSearchChatbox onBack(Runnable onBack) {
		this.onBack = onBack;
		return this;
	}

	private void filter() {
		results.clear();
		scrollOffset = 0;

		String search = getValue() == null ? "" : getValue().toLowerCase().trim();

		for (Choice choice : choices) {
			if (search.isEmpty() || choice.getSearchText().contains(search)) {
				results.add(choice);
			}
		}
	}

	private int maxScroll() {
		return Math.max(0, results.size() - visibleRows);
	}

	private void scrollBy(int rows) {
		int next = Math.max(0, Math.min(scrollOffset + rows, maxScroll()));

		if (next != scrollOffset) {
			scrollOffset = next;
			clientThread.invokeLater(this::update);
		}
	}

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent event) {
		if (!chatboxPanelManager.shouldTakeInput()) return event;
		if (results.size() <= visibleRows) return event;

		scrollBy(event.getWheelRotation());
		event.consume();
		return event;
	}

	@Override
	public void keyPressed(KeyEvent event) {
		if (!chatboxPanelManager.shouldTakeInput()) return;

		switch (event.getKeyCode()) {
			case KeyEvent.VK_UP:
				event.consume();
				scrollBy(-1);
				return;
			case KeyEvent.VK_DOWN:
				event.consume();
				scrollBy(1);
				return;
			case KeyEvent.VK_PAGE_UP:
				event.consume();
				scrollBy(-visibleRows);
				return;
			case KeyEvent.VK_PAGE_DOWN:
				event.consume();
				scrollBy(visibleRows);
				return;
			default:
				super.keyPressed(event);
		}
	}

	@Override
	protected void update() {
		Widget container = chatboxPanelManager.getContainerWidget();
		container.deleteAllChildren();

		Widget promptWidget = container.createChild(-1, WidgetType.TEXT);
		promptWidget.setText(getPrompt());
		promptWidget.setTextColor(0x800000);
		promptWidget.setFontId(getFontID());
		promptWidget.setOriginalX(0);
		promptWidget.setOriginalY(5);
		promptWidget.setXPositionMode(WidgetPositionMode.ABSOLUTE_CENTER);
		promptWidget.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
		promptWidget.setOriginalHeight(FONT_SIZE);
		promptWidget.setXTextAlignment(WidgetTextAlignment.CENTER);
		promptWidget.setYTextAlignment(WidgetTextAlignment.CENTER);
		promptWidget.setWidthMode(WidgetSizeMode.MINUS);
		promptWidget.revalidate();

		buildEdit(0, 5 + FONT_SIZE, container.getWidth(), FONT_SIZE);

		Widget separator = container.createChild(-1, WidgetType.LINE);
		separator.setOriginalX(0);
		separator.setOriginalY(8 + (FONT_SIZE * 2));
		separator.setXPositionMode(WidgetPositionMode.ABSOLUTE_CENTER);
		separator.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
		separator.setOriginalHeight(0);
		separator.setOriginalWidth(16);
		separator.setWidthMode(WidgetSizeMode.MINUS);
		separator.setTextColor(0x666666);
		separator.revalidate();

		int top = 12 + (FONT_SIZE * 2) + PADDING;
		int totalRows = Math.max(1, (container.getHeight() - top - PADDING) / LINE_HEIGHT);

		if (results.isEmpty()) {
			visibleRows = totalRows;
			caption(container, top, choices.isEmpty() ? "No voices available" : "No voices match that search");
			return;
		}

		boolean scrollable = results.size() > totalRows;
		visibleRows = scrollable ? Math.max(1, totalRows - 1) : totalRows;

		scrollOffset = Math.max(0, Math.min(scrollOffset, maxScroll()));

		int from = scrollOffset;
		int to = Math.min(from + visibleRows, results.size());
		int y = top;

		for (int i = from; i < to; i++) {
			final Choice choice = results.get(i);

			Widget row = container.createChild(-1, WidgetType.TEXT);
			row.setText(choice.getLabel());
			row.setFontId(getFontID());
			row.setTextColor(0);
			row.setOriginalX(PADDING);
			row.setOriginalY(y);
			row.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
			row.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
			row.setOriginalHeight(LINE_HEIGHT);
			row.setOriginalWidth(PADDING * 2);
			row.setWidthMode(WidgetSizeMode.MINUS);
			row.setXTextAlignment(WidgetTextAlignment.LEFT);
			row.setYTextAlignment(WidgetTextAlignment.CENTER);
			row.setAction(0, "Select");
			row.setHasListener(true);
			row.setOnOpListener((JavaScriptCallback) ev -> select(choice));
			row.setOnMouseOverListener((JavaScriptCallback) ev -> row.setTextColor(0xFFFFFF));
			row.setOnMouseLeaveListener((JavaScriptCallback) ev -> row.setTextColor(0));
			row.revalidate();

			y += LINE_HEIGHT;
		}

		if (scrollable) {
			caption(container, y, String.format("%d-%d of %d  -  %s", from + 1, to, results.size(), scrollHint(from, to)));
		}
	}

	private String scrollHint(int from, int to) {
		if (from == 0) return "scroll down for more";
		if (to == results.size()) return "scroll up for more";
		return "scroll up & down for more";
	}

	private void caption(Widget container, int y, String text) {
		Widget caption = container.createChild(-1, WidgetType.TEXT);
		caption.setText(text);
		caption.setFontId(getFontID());
		caption.setTextColor(0x666666);
		caption.setOriginalX(PADDING);
		caption.setOriginalY(y);
		caption.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
		caption.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
		caption.setOriginalHeight(LINE_HEIGHT);
		caption.setOriginalWidth(PADDING * 2);
		caption.setWidthMode(WidgetSizeMode.MINUS);
		caption.setXTextAlignment(WidgetTextAlignment.LEFT);
		caption.setYTextAlignment(WidgetTextAlignment.CENTER);
		caption.revalidate();
	}

	private void select(Choice choice) {
		onBack = null;
		chatboxPanelManager.close();

		if (onSelected != null) onSelected.accept(choice.getVoiceID());
	}

	@Override
	protected void close() {
		Runnable back = onBack;
		onBack = null;

		super.close();

		if (back != null) back.run();
	}

	@Value
	public static class Choice {
		String label;
		String searchText;
		VoiceID voiceID;

		public static Choice of(String label, VoiceID voiceID) {
			return new Choice(label, (label + " " + voiceID.toVoiceIDString()).toLowerCase(), voiceID);
		}
	}
}

package dev.phyce.naturalspeech.ui.layouts;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Insets;
import java.util.function.Function;

public class OnlyVisibleGridLayout extends GridLayout {

	public OnlyVisibleGridLayout() {
		this(1, 0, 0, 0);
	}

	public OnlyVisibleGridLayout(int rows, int columns) {
		this(rows, columns, 0, 0);
	}

	public OnlyVisibleGridLayout(int rows, int columns, int horizontalGap, int verticalGap) {
		super(rows, columns, horizontalGap, verticalGap);
	}

	// Pretends invisible components don't exist during layout
	private int getVisibleComponentCount(Container parent) {
		int count = 0;
		for (Component component : parent.getComponents()) {if (component.isVisible()) count++;}
		return count;
	}

	@Override
	public Dimension preferredLayoutSize(Container parent) {
		synchronized (parent.getTreeLock()) {
			return calculateSize(parent, Component::getPreferredSize);
		}
	}

	@Override
	public Dimension minimumLayoutSize(Container parent) {
		synchronized (parent.getTreeLock()) {
			return calculateSize(parent, Component::getMinimumSize);
		}
	}

	@Override
	public void layoutContainer(Container parent) {
		synchronized (parent.getTreeLock()) {
			final Insets insets = parent.getInsets();
			final int componentCount = parent.getComponentCount();
			final int visibleComponentCount = getVisibleComponentCount(parent);
			int rowCount = getRows();
			int columnCount = getColumns();

			if (visibleComponentCount == 0) return;

			if (rowCount > 0) {columnCount = (visibleComponentCount + rowCount - 1) / rowCount;}
			else {rowCount = (visibleComponentCount + columnCount - 1) / columnCount;}

			final int horizontalGap = getHgap();
			final int verticalGap = getVgap();

			// scaling factors
			final Dimension preferredDimension = preferredLayoutSize(parent);
			final Insets parentInsets = parent.getInsets();
			int widthBorder = parentInsets.left + parentInsets.right;
			int heightBorder = parentInsets.top + parentInsets.bottom;
			final double widthScale =
				(1.0 * parent.getWidth() - widthBorder) / (preferredDimension.width - widthBorder);
			final double heightScale =
				(1.0 * parent.getHeight() - heightBorder) / (preferredDimension.height - heightBorder);

			final int[] widths = new int[columnCount];
			final int[] heights = new int[rowCount];

			// calculate dimensions for all components + apply scaling
			{
				int visibleIndex = 0;
				int trueIndex = 0;
				while (trueIndex < componentCount) {
					final Component comp = parent.getComponent(trueIndex);

					if (!comp.isVisible()) {
						trueIndex++;
						continue;
					}

					final int row = visibleIndex / columnCount;
					final int column = visibleIndex % columnCount;
					final Dimension dimension = comp.getPreferredSize();

					dimension.width = (int) (widthScale * dimension.width);
					dimension.height = (int) (heightScale * dimension.height);

					if (widths[column] < dimension.width) widths[column] = dimension.width;
					if (heights[row] < dimension.height) heights[row] = dimension.height;

					visibleIndex++;
					trueIndex++;
				}
			}

			final int[] columnX = new int[columnCount];
			for (int column = 0, x = insets.left; column < columnCount; column++) {
				columnX[column] = x;
				x += widths[column] + horizontalGap;
			}

			final int[] rowY = new int[rowCount];
			for (int row = 0, y = insets.top; row < rowCount; row++) {
				rowY[row] = y;
				y += heights[row] + verticalGap;
			}

			// Apply new bounds to all child components
			int visibleIndex = 0;
			int trueIndex = 0;
			while (trueIndex < componentCount) {
				final Component comp = parent.getComponent(trueIndex);

				if (!comp.isVisible()) {
					trueIndex++;
					continue;
				}

				final int row = visibleIndex / columnCount;
				final int column = visibleIndex % columnCount;
				comp.setBounds(columnX[column], rowY[row], widths[column], heights[row]);
				visibleIndex++;
				trueIndex++;
			}
		}
	}

	/**
	 * Calculate outer size of the layout based on it's children and sizer
	 *
	 * @param parent parent component
	 * @param sizer  functioning returning dimension of the child component
	 *
	 * @return outer size
	 */
	private Dimension calculateSize(final Container parent, final Function<Component, Dimension> sizer) {
		final int visibleComponentCount = getVisibleComponentCount(parent);
		final int componentCount = parent.getComponentCount();
		int rowCount = getRows();
		int columnCount = getColumns();

		if (rowCount > 0) {columnCount = (visibleComponentCount + rowCount - 1) / rowCount;}
		else {rowCount = (visibleComponentCount + columnCount - 1) / columnCount;}

		final int[] width = new int[columnCount];
		final int[] height = new int[rowCount];

		// Calculate dimensions for all components
		int visibleIndex = 0;
		int trueIndex = 0;
		while (trueIndex < componentCount) {
			final Component comp = parent.getComponent(trueIndex);

			if (!comp.isVisible()) {
				trueIndex++;
				continue;
			}

			final int row = visibleIndex / columnCount;
			final int column = visibleIndex % columnCount;
			final Dimension dimension = sizer.apply(comp);

			if (width[column] < dimension.width) width[column] = dimension.width;
			if (height[row] < dimension.height) height[row] = dimension.height;

			visibleIndex++;
			trueIndex++;
		}

		// Calculate total width and height of the layout
		int netWidth = 0;

		for (int j = 0; j < columnCount; j++) {netWidth += width[j];}

		int netHeight = 0;

		for (int i = 0; i < rowCount; i++) {netHeight += height[i];}

		final Insets insets = parent.getInsets();

		// Apply insets and horizontal and vertical gap to layout
		return new Dimension(
			insets.left + insets.right + netWidth + (columnCount - 1) * getHgap(),
			insets.top + insets.bottom + netHeight + (rowCount - 1) * getVgap()
		);
	}
}

