package dev.phyce.naturalspeech.utils;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public final class TextUtil {

	public static List<String> splitSentence(String sentence) {
		final int softLimit = 40;
		final int hardLimit = 80;
		List<String> fragments = new ArrayList<>();
		StringBuilder currentFragment = new StringBuilder();

		List<String> tokens = tokenize(sentence);

		for (String token : tokens) {
			if (currentFragment.length() + token.length() <= hardLimit) {
				currentFragment.append(token);

				if (token.matches(".*[.!?]$")) {
					fragments.add(currentFragment.toString().trim());
					currentFragment.setLength(0);
					continue;
				}

				if (token.matches(".*[,-;/]$") && currentFragment.length() > softLimit) {
					fragments.add(currentFragment.toString().trim());
					currentFragment.setLength(0);
					continue;
				}
			}
			else {
				int lastBreakPoint = findLastBreakPoint(currentFragment.toString(), softLimit, hardLimit);
				if (lastBreakPoint > 0) {
					fragments.add(currentFragment.substring(0, lastBreakPoint).trim());
					currentFragment = new StringBuilder(currentFragment.substring(lastBreakPoint).trim());
				}
				else {
					fragments.add(currentFragment.toString().trim());
					currentFragment.setLength(0);
				}
				currentFragment.append(token);
			}

			if (!token.matches("\\p{Punct}")) currentFragment.append(" ");
		}

		if (currentFragment.length() > 0) fragments.add(currentFragment.toString().trim());

		return fragments;
	}

	private static int findLastBreakPoint(String fragment, int softLimit, int hardLimit) {
		int lastSpace = -1;

		for (int i = 0; i < fragment.length(); i++) {
			if (fragment.charAt(i) == ' ' || fragment.charAt(i) == ',') {lastSpace = i + 1;}
			else if (fragment.charAt(i) == '.' || fragment.charAt(i) == '!' || fragment.charAt(i) == '?') return i + 1;
		}
		return lastSpace;
	}

	private static final String VALID_MATCH_TAILS = " ,.!?;:";

	public static String expandShortenedPhrases(String text, Map<String, String> phrases) {
		for (Map.Entry<String, String> entry : phrases.entrySet()) {
			text = applyPhraseReplacement(text, entry.getKey(), entry.getValue());
		}
		return text;
	}

	private static String applyPhraseReplacement(String text, String key, String replacement) {
		if (key == null || key.isEmpty()) return text;
		String lowerText = text.toLowerCase();
		String lowerKey = key.toLowerCase();
		StringBuilder result = new StringBuilder();
		int prev = 0;
		int head = lowerText.indexOf(lowerKey);
		while (head != -1) {
			result.append(text, prev, head);
			int tail = head + lowerKey.length();
			boolean precededOk = head == 0 || text.charAt(head - 1) == ' ';
			boolean followedOk = tail == text.length() || VALID_MATCH_TAILS.indexOf(text.charAt(tail)) >= 0;
			if (precededOk && followedOk) {
				result.append(replacement);
			} else {
				result.append(text, head, tail);
			}
			prev = tail;
			head = lowerText.indexOf(lowerKey, prev);
		}
		if (prev < text.length()) {
			result.append(text, prev, text.length());
		}
		return result.toString();
	}

	public static List<String> tokenize(String text) {
		List<String> tokens = new ArrayList<>();
		Matcher matcher = Pattern.compile("[^\\s]+").matcher(text);

		while (matcher.find()) tokens.add(matcher.group());

		return tokens;
	}

	public static final Pattern patternAnyAlphaNumericChar = Pattern.compile(".*[A-Za-z0-9À-ÖØ-öø-ÿ].*");
	public static boolean containAlphaNumeric(String text) {
		return patternAnyAlphaNumericChar.matcher(text).matches();
	}

	public static String renderLargeNumbers(String text) {
		text = text.replaceAll("(?i)(\\d+)\\s?k\\b", "$1 thousand");
		text = text.replaceAll("(?i)(\\d+)\\s?m\\b", "$1 million");
		text = text.replaceAll("(?i)(\\d+)\\s?b\\b", "$1 billion");
		text = text.replaceAll("(?i)(\\d+)\\s?t\\b", "$1 trillion");
		return text;
	}

	private static final Pattern NUMERIC_COMMA_PATTERN = Pattern.compile("\\d{1,3}(,\\d{3})+");
	public static String removeNumericCommas(String input) {
		Matcher matcher = NUMERIC_COMMA_PATTERN.matcher(input);
		StringBuilder result = new StringBuilder();
		while (matcher.find()) {
			matcher.appendReplacement(result, matcher.group().replace(",", ""));
		}
		matcher.appendTail(result);
		return result.toString();
	}

	public static String escape(String text) {
		return text.replace("\\", "\\\\")
			.replace("\"", "\\\"")
			.replace("\b", "\\b")
			.replace("\f", "\\f")
			.replace("\n", "\\n")
			.replace("\r", "\\r")
			.replace("\t", "\\t");
	}

	public static String generateJson(String text, int voiceId) {
		text = escape(text);
		if(voiceId == -1) return String.format("{\"text\":\"%s\"}", text);
		else return String.format("{\"text\":\"%s\", \"speaker_id\":%d}", text, voiceId);
	}

	private static final Pattern patternTargetWithLevel = Pattern.compile("(.+)  \\(level-\\d+\\)");
	/**
	 * For MenuEntry menuTarget name.
	 * Keeps tag information, removes level information.
	 * For example <col=ffffff>Guard</col>  (level-32) -> Guard
	 * @return
	 */
	public static String removeLevelFromTargetName(String menuTarget) {
		Matcher matcher = patternTargetWithLevel.matcher(menuTarget);
		if (matcher.matches()) menuTarget = matcher.group(1);
		return menuTarget;
	}

	public static String removeTags(String input) {
		return input.replaceAll("<[^>]+>", "");
	}

	private static final Pattern CHAT_TAG_PATTERN = Pattern.compile("<(?!lt>|gt>)[^>]+>");

	public static String stripChatTags(String text) {
		return CHAT_TAG_PATTERN.matcher(text).replaceAll("")
			.replace("<lt>", "<")
			.replace("<gt>", ">");
	}

}

